func fetchWithRetry(attempts: Int = 3) async throws -> Data {
    for attempt in 0..<attempts {
        do { return try await fetchData() }
        catch { if attempt == attempts - 1 { throw error } }
        try await Task.sleep(for: .seconds(pow(2.0, Double(attempt))))
    }
    fatalError("unreachable")
}

